type IconProps = { className?: string }

function IconSvg({
  className,
  viewBox = '0 0 24 24',
  children,
}: IconProps & { viewBox?: string; children: ReactNode }) {
  return (
    <svg
      viewBox={viewBox}
      fill="currentColor"
      aria-hidden
      focusable="false"
      className={cn('size-4 shrink-0', className)}
    >
      {children}
    </svg>
  )
}

